-- Import historical transactions from 2026_09_29_20_12_13_529074.mmbackup for Freedom user_id=4.
-- Source contains 1,941 active transactions (70 income, 1,871 expense), all PLN.
-- Historical net cash flow is +18,321.46 PLN, equal to the source app account balance.
-- Imported transactions receive exact dates, amounts, descriptions and source category names.
-- Money provenance is reconstructed without touching existing lots: all imported income lots are
-- created first, then imported expenses consume only those imported lots FIFO. This is necessary
-- because the source app did not preserve provenance and some back-dated periods are negative.

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM users WHERE id = 4) THEN
        RAISE EXCEPTION 'MMBackup import requires existing user id=4';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM assets WHERE user_id=4 AND system_cash=TRUE) THEN
        RAISE EXCEPTION 'MMBackup import requires system cash asset for user id=4';
    END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Ledger bootstrap
--
-- This import is intentionally self-contained. The user's current database can
-- be on the pre-ledger schema (V24), so create the V25 structures here when
-- they are missing. This keeps this single SQL file sufficient for the import.
-- ---------------------------------------------------------------------------
ALTER TABLE transactions ADD COLUMN IF NOT EXISTS asset_id BIGINT NULL;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conrelid = 'transactions'::regclass
          AND conname = 'fk_transactions_asset'
    ) THEN
        ALTER TABLE transactions
            ADD CONSTRAINT fk_transactions_asset
            FOREIGN KEY (asset_id) REFERENCES assets(id) ON DELETE SET NULL;
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS ix_transactions_asset_id
    ON transactions(asset_id);

-- Existing historical transactions predate source-account tracking. Point them
-- at each user's system cash so the application has a deterministic source.
UPDATE transactions t
SET asset_id = a.id
FROM assets a
WHERE t.user_id = a.user_id
  AND a.system_cash = TRUE
  AND t.asset_id IS NULL;

CREATE TABLE IF NOT EXISTS money_lots (
    id BIGSERIAL PRIMARY KEY,
    user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    origin_type VARCHAR(40) NOT NULL,
    origin_transaction_id BIGINT NULL REFERENCES transactions(id) ON DELETE CASCADE,
    origin_asset_id BIGINT NULL REFERENCES assets(id) ON DELETE SET NULL,
    original_amount NUMERIC(19,2) NOT NULL CHECK (original_amount > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS ix_money_lots_user
    ON money_lots(user_id,id);
CREATE INDEX IF NOT EXISTS ix_money_lots_transaction
    ON money_lots(origin_transaction_id)
    WHERE origin_transaction_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS money_positions (
    id BIGSERIAL PRIMARY KEY,
    user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    lot_id BIGINT NOT NULL REFERENCES money_lots(id) ON DELETE CASCADE,
    asset_id BIGINT NOT NULL REFERENCES assets(id) ON DELETE CASCADE,
    amount NUMERIC(19,2) NOT NULL CHECK (amount >= 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(lot_id,asset_id)
);
CREATE INDEX IF NOT EXISTS ix_money_positions_asset
    ON money_positions(user_id,asset_id,id);

CREATE TABLE IF NOT EXISTS transaction_lot_usages (
    id BIGSERIAL PRIMARY KEY,
    user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    transaction_id BIGINT NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,
    lot_id BIGINT NOT NULL REFERENCES money_lots(id) ON DELETE CASCADE,
    asset_id BIGINT NULL REFERENCES assets(id) ON DELETE SET NULL,
    amount NUMERIC(19,2) NOT NULL CHECK (amount > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS ix_transaction_lot_usages_transaction
    ON transaction_lot_usages(transaction_id);
CREATE INDEX IF NOT EXISTS ix_transaction_lot_usages_lot
    ON transaction_lot_usages(lot_id);

CREATE TABLE IF NOT EXISTS money_movements (
    id BIGSERIAL PRIMARY KEY,
    user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    lot_id BIGINT NULL REFERENCES money_lots(id) ON DELETE SET NULL,
    movement_type VARCHAR(40) NOT NULL,
    source_asset_id BIGINT NULL REFERENCES assets(id) ON DELETE SET NULL,
    target_asset_id BIGINT NULL REFERENCES assets(id) ON DELETE SET NULL,
    transaction_id BIGINT NULL REFERENCES transactions(id) ON DELETE SET NULL,
    amount NUMERIC(19,2) NOT NULL CHECK (amount > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS ix_money_movements_user_created
    ON money_movements(user_id,created_at DESC,id DESC);

-- Reconstruct only balances that are not represented in the ledger yet. This
-- covers the pre-ledger database without duplicating balances if these tables
-- already exist.
    user_id, origin_type, origin_asset_id, original_amount, created_at
)
SELECT
    a.user_id, 'LEGACY_BALANCE', a.id, a.value, NOW()
FROM assets a
WHERE a.value > 0
  AND NOT EXISTS (
      SELECT 1
      FROM money_lots l
      WHERE l.user_id = a.user_id
        AND l.origin_type = 'LEGACY_BALANCE'
        AND l.origin_asset_id = a.id
  )
  AND NOT EXISTS (
      SELECT 1
      FROM money_positions p
      WHERE p.user_id = a.user_id
        AND p.asset_id = a.id
        AND p.amount > 0
  );

    user_id, lot_id, asset_id, amount, created_at, updated_at
)
SELECT
    l.user_id, l.id, l.origin_asset_id, l.original_amount, l.created_at, l.created_at
FROM money_lots l
WHERE l.origin_type = 'LEGACY_BALANCE'
  AND l.origin_asset_id IS NOT NULL
  AND NOT EXISTS (
      SELECT 1
      FROM money_positions p
      WHERE p.lot_id = l.id
        AND p.asset_id = l.origin_asset_id
  );

ALTER TABLE transactions ADD COLUMN IF NOT EXISTS import_source VARCHAR(64);
ALTER TABLE transactions ADD COLUMN IF NOT EXISTS external_id VARCHAR(128);
CREATE UNIQUE INDEX IF NOT EXISTS ux_transactions_import_external
    ON transactions(user_id, import_source, external_id)
    WHERE import_source IS NOT NULL AND external_id IS NOT NULL;

CREATE TEMP TABLE mm_import_categories (
    type VARCHAR(16) NOT NULL,
    name VARCHAR(120) NOT NULL,
    group_key VARCHAR(32) NOT NULL,
    icon_key VARCHAR(80) NOT NULL,
    color VARCHAR(16) NOT NULL,
    slug VARCHAR(80)
) ON COMMIT DROP;

-- Reuse an existing Freedom category when type+name already match (case-insensitive).
-- Otherwise preserve the exact category name from the backup.
SELECT 4, c.type, c.group_key,
       'mm-' || substr(md5(c.type || ':' || lower(c.name)),1,32),
       c.name, c.icon_key, c.color, FALSE, TRUE, 2000 + row_number() OVER (ORDER BY c.type,c.name)
FROM mm_import_categories c
WHERE NOT EXISTS (
    SELECT 1 FROM categories x
    WHERE x.user_id=4 AND x.type=c.type AND lower(x.name)=lower(c.name)
);

CREATE TEMP TABLE mm_import_transactions (
    external_id VARCHAR(128) PRIMARY KEY,
    source_created_at TIMESTAMPTZ NOT NULL,
    type VARCHAR(20) NOT NULL,
    amount NUMERIC(19,2) NOT NULL,
    transaction_date DATE NOT NULL,
    name VARCHAR(255) NOT NULL,
    category_type VARCHAR(16),
    category_name VARCHAR(120)
) ON COMMIT DROP;

-- Insert the transaction history. asset_id points at user 4's system cash.
    user_id,type,name,amount,category,category_id,recurring,transaction_date,recurring_rule_id,asset_id,import_source,external_id
)
SELECT
    4, s.type, s.name, s.amount,
    CASE
      WHEN s.type='INCOME' THEN NULL
      WHEN c.group_key='FIXED' THEN 'FIXED'
      WHEN c.group_key='WEALTH' THEN 'INVESTMENT'
      WHEN c.group_key='GOALS' THEN 'GOAL'
      ELSE 'LIVING'
    END,
    c.id, FALSE, s.transaction_date, NULL, cash.id, 'MMBACKUP_2026_09_29', s.external_id
FROM mm_import_transactions s
CROSS JOIN LATERAL (
    SELECT id FROM assets WHERE user_id=4 AND system_cash=TRUE LIMIT 1
) cash
LEFT JOIN LATERAL (
    SELECT id,group_key FROM categories
    WHERE user_id=4 AND type=s.category_type AND lower(name)=lower(s.category_name)
    ORDER BY system_default DESC,id
    LIMIT 1
) c ON s.category_name IS NOT NULL
WHERE NOT EXISTS (
    SELECT 1 FROM transactions t
    WHERE t.user_id=4 AND t.import_source='MMBACKUP_2026_09_29' AND t.external_id=s.external_id
);

-- Reconstruct provenance for imported income. Existing Freedom capital is not consumed by this import.
SELECT 4,'INCOME',t.id,t.asset_id,t.amount,s.source_created_at
FROM transactions t
JOIN mm_import_transactions s ON s.external_id=t.external_id
WHERE t.user_id=4 AND t.import_source='MMBACKUP_2026_09_29' AND t.type='INCOME'
  AND NOT EXISTS (SELECT 1 FROM money_lots l WHERE l.user_id=4 AND l.origin_transaction_id=t.id AND l.origin_type='INCOME');
SELECT 4,l.id,l.origin_asset_id,l.original_amount,l.created_at,l.created_at
FROM money_lots l
JOIN transactions t ON t.id=l.origin_transaction_id
WHERE t.user_id=4 AND t.import_source='MMBACKUP_2026_09_29' AND t.type='INCOME'
  AND NOT EXISTS (SELECT 1 FROM money_positions p WHERE p.lot_id=l.id AND p.asset_id=l.origin_asset_id);
SELECT 4,l.id,'INCOME',NULL,l.origin_asset_id,t.id,t.amount,s.source_created_at
FROM transactions t
JOIN mm_import_transactions s ON s.external_id=t.external_id
JOIN money_lots l ON l.origin_transaction_id=t.id AND l.origin_type='INCOME'
WHERE t.user_id=4 AND t.import_source='MMBACKUP_2026_09_29';

-- Allocate every imported expense against imported income lots (FIFO by source transaction date/id).
-- We intentionally do not require the lot to pre-date the expense: the old app permitted back-dated
-- entries, and its cumulative history is temporarily negative despite ending at the exact account balance.
DO $$
DECLARE
    e RECORD;
    p RECORD;
    remaining NUMERIC(19,2);
    used_amount NUMERIC(19,2);
BEGIN
    FOR e IN
        SELECT t.id,t.asset_id,t.amount,s.source_created_at
        FROM transactions t
        JOIN mm_import_transactions s ON s.external_id=t.external_id
        WHERE t.user_id=4 AND t.import_source='MMBACKUP_2026_09_29' AND t.type='EXPENSE'
        ORDER BY t.transaction_date,s.source_created_at,t.id
    LOOP
        remaining := e.amount;

        FOR p IN
            SELECT mp.id AS position_id,mp.lot_id,mp.amount
            FROM money_positions mp
            JOIN money_lots ml ON ml.id=mp.lot_id
            JOIN transactions income_tx ON income_tx.id=ml.origin_transaction_id
            WHERE mp.user_id=4
              AND mp.asset_id=e.asset_id
              AND mp.amount>0
              AND income_tx.user_id=4
              AND income_tx.import_source='MMBACKUP_2026_09_29'
              AND income_tx.type='INCOME'
            ORDER BY income_tx.transaction_date,income_tx.id,mp.id
        LOOP
            EXIT WHEN remaining <= 0;
            used_amount := LEAST(p.amount, remaining);

            UPDATE money_positions
            SET amount=amount-used_amount, updated_at=e.source_created_at
            WHERE id=p.position_id;

            VALUES(4,e.id,p.lot_id,e.asset_id,used_amount,e.source_created_at);

            VALUES(4,p.lot_id,'EXPENSE',e.asset_id,NULL,e.id,used_amount,e.source_created_at);

            remaining := remaining-used_amount;
        END LOOP;

        IF remaining > 0 THEN
            RAISE EXCEPTION 'MMBackup import: imported income lots do not cover expense transaction %, missing %', e.id, remaining;
        END IF;
    END LOOP;
END $$;

DELETE FROM money_positions p
USING money_lots l, transactions t
WHERE p.lot_id=l.id AND l.origin_transaction_id=t.id
  AND t.user_id=4 AND t.import_source='MMBACKUP_2026_09_29' AND p.amount=0;

-- Apply the imported history's net effect once. Imported positions have the same +18,321.46 net delta,
-- so assets.value and the provenance ledger remain reconciled.
UPDATE assets a
SET value = a.value + x.net_amount
FROM (
    SELECT COALESCE(SUM(CASE WHEN type='INCOME' THEN amount ELSE -amount END),0) AS net_amount
    FROM mm_import_transactions
) x
WHERE a.user_id=4 AND a.system_cash=TRUE;

DO $$
DECLARE
    imported_count INTEGER;
    imported_net NUMERIC(19,2);
    imported_positions NUMERIC(19,2);
BEGIN
    SELECT COUNT(*), COALESCE(SUM(CASE WHEN type='INCOME' THEN amount ELSE -amount END),0)
      INTO imported_count, imported_net
    FROM transactions
    WHERE user_id=4 AND import_source='MMBACKUP_2026_09_29';

    SELECT COALESCE(SUM(mp.amount),0) INTO imported_positions
    FROM money_positions mp
    JOIN money_lots ml ON ml.id=mp.lot_id
    JOIN transactions t ON t.id=ml.origin_transaction_id
    WHERE t.user_id=4 AND t.import_source='MMBACKUP_2026_09_29';

    IF imported_count <> 1941 THEN
        RAISE EXCEPTION 'MMBackup import validation failed: expected 1941 transactions, got %', imported_count;
    END IF;
    IF imported_net <> 18321.46 THEN
        RAISE EXCEPTION 'MMBackup import validation failed: expected net 18321.46, got %', imported_net;
    END IF;
    IF imported_positions <> 18321.46 THEN
        RAISE EXCEPTION 'MMBackup ledger validation failed: expected open imported positions 18321.46, got %', imported_positions;
    END IF;
END $$;
